// PORT: `into`/`try_from` serialize these enums as their Go `int32` ordinals.
// Deserialization rejects out-of-range values; Go would accept them into the
// open `int32` newtype — a malformed-JSON-only divergence.

macro_rules! serde_i32_enum {
    ($name:ident, $($variant:ident = $value:expr),+ $(,)?) => {
        impl From<$name> for i32 {
            fn from(v: $name) -> i32 {
                v as i32
            }
        }

        impl TryFrom<i32> for $name {
            type Error = String;
            fn try_from(value: i32) -> Result<Self, Self::Error> {
                match value {
                    $($value => Ok(Self::$variant),)+
                    _ => Err(format!("invalid value {value} for {}", stringify!($name))),
                }
            }
        }
    };
}

