// PORT: `map[ModuleKind]ModuleResolutionKind` becomes a LazyLock map;
// lookups `.get(&kind).copied().unwrap_or_default()` reproduce Go's
// missing-key zero value (ModuleResolutionKindUnknown).
pub static MODULE_KIND_TO_MODULE_RESOLUTION_KIND: LazyLock<
    rustc_hash::FxHashMap<ModuleKind, ModuleResolutionKind>,
> = LazyLock::new(|| {
    let mut m = rustc_hash::FxHashMap::default();
    m.insert(ModuleKind::Node16, ModuleResolutionKind::Node16);
    m.insert(ModuleKind::NodeNext, ModuleResolutionKind::NodeNext);
    m
});

// PORT: Go's `String()` methods panic on the zero value and on unhandled
// cases; `Display` reproduces that.
impl std::fmt::Display for ModuleResolutionKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ModuleResolutionKind::Unknown => {
                panic!("should not use zero value of ModuleResolutionKind")
            }
            ModuleResolutionKind::Classic => f.write_str("Classic"),
            ModuleResolutionKind::Node10 => f.write_str("Node10"),
            ModuleResolutionKind::Node16 => f.write_str("Node16"),
            ModuleResolutionKind::NodeNext => f.write_str("NodeNext"),
            ModuleResolutionKind::Bundler => f.write_str("Bundler"),
        }
    }
}

impl std::fmt::Display for JsxEmit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            JsxEmit::None => panic!("should not use zero value of JsxEmit"),
            JsxEmit::Preserve => f.write_str("preserve"),
            JsxEmit::React => f.write_str("react"),
            JsxEmit::ReactNative => f.write_str("react-native"),
            JsxEmit::ReactJSX => f.write_str("react-jsx"),
            JsxEmit::ReactJSXDev => f.write_str("react-jsxdev"),
        }
    }
}

